#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<int> l(n);
    for (int i = 0; i < n; ++i) {
        cin >> l[i];
    }
    vector<int> partA(l.begin(), l.begin() + n / 2);
    vector<int> partB(l.begin() + n / 2, l.end());

    int lenA = n / 2;
    int lenB = n - lenA;
    int totalA = 1 << lenA;
    int totalB = 1 << lenB;

    vector<int> sumsA;
    for (int mask = 0; mask < totalA; ++mask) {
        int sum_value = 0;
        for (int i = 0; i < lenA; ++i) {
            if (mask & (1 << i)) {
                sum_value += partA[i];
            }
        }
        sumsA.push_back(sum_value % m);
    }

    vector<int> sumsB;
    for (int mask = 0; mask < totalB; ++mask) {
        int sum_value = 0;
        for (int i = 0; i < lenB; ++i) {
            if (mask & (1 << i)) {
                sum_value += partB[i];
            }
        }
        sumsB.push_back(sum_value % m);
    }

    sort(sumsA.begin(), sumsA.end());
    sort(sumsB.begin(), sumsB.end());

    int max_mod = 0;

    auto binary_search_closest = [&](const vector<int>& l, int x) {
        int low = 0, high = (int)l.size() - 1;
        int answer = 0;
        while (low <= high) {
            int mid = (low + high) / 2;
            if (l[mid] < x) {
                answer = l[mid];
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return answer;
    };

    for (int s : sumsA) {
        int req = m - s;
        int pair = binary_search_closest(sumsB, req);
        max_mod = max(max_mod, (s + pair) % m);
    }

    cout << max_mod << "\n";

    return 0;
}
